def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 900:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    pressure = 0.0
    if highest_prev >= 140:
        pressure += 18
    elif highest_prev >= 130:
        pressure += 12
    elif highest_prev >= 100:
        pressure += 7
    else:
        pressure += 3

    pressure += desperate_count * 4
    pressure += rich_count * 2

    if supply <= 16:
        pressure += 18
    elif supply <= 18:
        pressure += 12
    elif supply >= 23:
        pressure -= 10
    elif supply >= 21:
        pressure -= 5

    urgency = 0.0
    if hp <= 2:
        urgency += 40
    elif hp <= 4:
        urgency += 24
    elif hp <= 6:
        urgency += 12

    if no_water_days >= 2:
        urgency += 35
    elif no_water_days >= 1:
        urgency += 18

    if day >= 8:
        urgency += 8

    base = 62.0 + pressure + urgency

    if supply >= 22 and hp >= 7 and no_water_days == 0:
        base -= 18
    if supply >= 24 and hp >= 9:
        base -= 10

    if highest_prev > 0:
        target = max(base, highest_prev + 2.5)
    else:
        target = base

    if hp <= 2 or no_water_days >= 2:
        target = max(target, 132.0)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, 108.0)

    if budget < 120:
        target = min(target, budget)
    elif budget < 250:
        target = min(target, budget * 0.72)
    elif budget < 450:
        target = min(target, budget * 0.55)
    else:
        target = min(target, budget * 0.32 + 35)

    if supply >= 23 and hp >= 8 and no_water_days == 0:
        target = min(target, 88.0)

    if target < 0:
        target = 0.0
    if target > budget:
        target = float(budget)

    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    top_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are available (integer count)
    # supply is float; compute integer units safely
    units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    # If supply is low, competition is harsher; bid slightly higher.
    low_supply = supply <= float(MIN_SUPPLY) + 0.5

    # Urgency factor from my hp and consecutive no-water days
    urgency = 0.0
    if hp <= 1:
        urgency = 1.0
    elif hp == 2:
        urgency = 0.85
    elif hp == 3:
        urgency = 0.65
    else:
        urgency = 0.45

    if no_water_days >= 2:
        urgency = max(urgency, 0.9)

    # Base bid: try to stay competitive against the highest yesterday bidder,
    # but do not overpay when my hp is healthy.
    # Aim: slightly above top_prev_bid when urgency is high; otherwise around mid-high.
    if top_prev_bid > 0:
        if urgency >= 0.8:
            target = top_prev_bid + (DAILY_SALARY * 0.05)
        else:
            target = max(top_prev_bid * 0.85, DAILY_SALARY * 0.55)
    else:
        target = DAILY_SALARY * 0.55

    if low_supply and urgency < 0.8:
        target = max(target, DAILY_SALARY * 0.65)

    # If I have very low hp, push closer to budget cap.
    if hp <= 2:
        target = max(target, DAILY_SALARY * (0.75 + 0.15 * (1 - hp)))

    # Cap by budget and keep within plausible range
    # Also ensure non-negative
    cap = budget
    if cap <= 0:
        return 0.0

    bid = min(cap, target)

    # If units are 0 (supply < WATER_REQ), any bid likely loses; still bid minimal to preserve budget.
    if units <= 0:
        bid = min(bid, DAILY_SALARY * 0.25)

    # Final safety clamp
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # 1. If no opponents, bid low to save budget, but ensure water if needed.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1) if my_status['budget'] > 0 else 0.0

    # 2. Critical HP: If close to death, bid very high.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # 3. Collect yesterday's bids from alive opponents.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # 4. Determine base bid based on supply scarcity and opponent behavior.
    total_water_needed_by_all = WATER_REQ # My requirement
    for opp in alive_opponents:
        total_water_needed_by_all += opp['water_requirement']

    is_supply_scarce = day_context['supply'] < total_water_needed_by_all * 0.8 

    bid_amount = DAILY_SALARY * 0.55 # Default moderate bid

    if is_supply_scarce:
        if max_yesterday_bid > DAILY_SALARY * 0.7:
            bid_amount = max(bid_amount, max_yesterday_bid + 5.0)
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.8)
    else:
        if max_yesterday_bid > DAILY_SALARY * 0.8:
            bid_amount = max(bid_amount, max_yesterday_bid + 1.0)
        elif max_yesterday_bid > DAILY_SALARY * 0.5:
            bid_amount = max(bid_amount, max_yesterday_bid * 1.05)

    # 5. Adjust bid based on my HP (if not critical, but getting low)
    if my_status['hp'] <= 4:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.75)

    # 6. Adjust bid for end-game
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.9)
    elif remaining_days <= 4:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.7)

    # 7. If I have no_water_days, it means I'm not getting water, so need to be more aggressive
    if my_status['no_water_days'] > 0:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.85)

    # 8. Final checks and budget constraint
    final_bid = min(my_status['budget'], bid_amount)
    final_bid = max(0.0, final_bid) # Ensure non-negative

    return float(final_bid)

